// Re-export catalog proto types.
// Generated by buf (buf.gen.rust.yaml) into gen/gitstore/catalog/v1/.
pub use super::validation_handler::catalog_proto;

use catalog_proto::catalog_service_client::CatalogServiceClient;
use catalog_proto::AdmitResourcesRequest;

/// Implements `AdmissionHandler` for the post-receive slot.
/// Catalog admission follows `branch_pattern`. Other heads containing RBAC
/// notify only that reserved subtree; the API verifies its canonical branch.
/// Always returns `Accept`.
pub struct AdmissionControlHandler {
    service_token: String,
    client: CatalogServiceClient<tonic::transport::Channel>,
    branch_pattern: Regex,
}

impl AdmissionControlHandler {
    pub fn new(
        client: CatalogServiceClient<tonic::transport::Channel>,
        branch_pattern: Regex,
    ) -> Self {
        Self {
            service_token: String::new(),
            client,
            branch_pattern,
        }
    }

    pub fn with_service_token(mut self, secret: &str) -> Self {
        self.service_token = secret.to_string();
        self
    }

    pub async fn connect(url: &str, branch_pattern: String) -> anyhow::Result<Self> {
        let re = Regex::new(&branch_pattern)
            .map_err(|e| anyhow::anyhow!("invalid branch_pattern {:?}: {}", branch_pattern, e))?;
        let endpoint = tonic::transport::Endpoint::from_shared(url.to_string())?;
        let channel = endpoint.connect_lazy();
        let client = CatalogServiceClient::new(channel);
        Ok(Self::new(client, re))
    }

    pub async fn replay_committed(
        &self,
        store: Arc<AdmissionReceiptStore>,
        id: ReceiptId,
        data_root: &Path,
        repository_lock: Arc<tokio::sync::RwLock<()>>,
    ) -> anyhow::Result<()> {
        let loading_store = Arc::clone(&store);
        let loading_id = id.clone();
        let data_root = data_root.to_path_buf();
        let (authorization, catalog_refs, git_dir) = crate::spawn_blocking(move || {
            let (authorization, catalog_refs) =
                loading_store.load_committed_delivery(&loading_id)?;
            let git_dir = crate::git::repo::fanout_path(&data_root, &authorization.repository_id)?;
            let repo = crate::git::repo::open_repository(&git_dir)?;
            // Missing retained objects must not look like an empty RBAC tree.
            for update in &authorization.refs {
                if !catalog_refs.contains(&update.ref_name)
                    && !update.ref_name.starts_with("refs/heads/")
                {
                    continue;
                }
                for oid in [&update.old_commit_sha, &update.new_commit_sha] {
                    let oid = gix::ObjectId::from_hex(oid.as_bytes())?;
                    if !oid.is_null() {
                        repo.find_commit(oid)?.tree()?.decode()?;
                    }
                }
            }
            Ok::<_, anyhow::Error>((authorization, catalog_refs, git_dir))
        })
        .await??;
        let actor = authorization
            .actor
            .as_ref()
            .ok_or_else(|| anyhow::anyhow!("receipt actor required"))?;
        let context = HookContext {
            repository_id: authorization.repository_id.clone(),
            receive_id: authorization.receive_id.clone(),
            actor_subject: actor.subject.clone(),
            actor_auth_method: actor.auth_method.clone(),
            actor_issuer: actor.issuer.clone(),
            actor_groups: actor.groups.clone(),
            actor_service_account_uid: actor.service_account_uid.clone(),
            ..HookContext::default()
        };
        let updates: Vec<_> = authorization
            .refs
            .iter()
            .map(|update| RefUpdate {
                ref_name: update.ref_name.clone(),
                old_oid: update.old_commit_sha.clone(),
                new_oid: update.new_commit_sha.clone(),
            })
            .collect();
        for request in Self::callback_requests_for_refs(
            &updates,
            &authorization.repository_id,
            &git_dir,
            &context,
            catalog_refs,
        )
        .await?
        {
            deliver_admission_callback(
                self.client.clone(),
                request,
                &self.service_token,
                Duration::from_secs(30),
            )
            .await?;
        }
        let write_guard = repository_lock.write_owned().await;
        crate::spawn_blocking(move || {
            let _guard = write_guard;
            let repository = crate::git::repo::open_repository(&git_dir)?;
            store.acknowledge_fenced(&repository, &id)
        })
        .await??;
        Ok(())
    }

    async fn callback_requests(
        &self,
        updates: &[RefUpdate],
        repository_id: &str,
        git_dir: &Path,
        hook_ctx: &HookContext,
    ) -> anyhow::Result<Vec<AdmitResourcesRequest>> {
        Self::callback_requests_for_refs(
            updates,
            repository_id,
            git_dir,
            hook_ctx,
            self.receipt_catalog_refs(updates),
        )
        .await
    }

    async fn callback_requests_for_refs(
        updates: &[RefUpdate],
        repository_id: &str,
        git_dir: &Path,
        hook_ctx: &HookContext,
        catalog_refs: Vec<String>,
    ) -> anyhow::Result<Vec<AdmitResourcesRequest>> {
        let matching_updates: Vec<_> = updates
            .iter()
            .filter(|update| {
                catalog_refs.contains(&update.ref_name)
                    || update.ref_name.starts_with("refs/heads/")
            })
            .cloned()
            .collect();
        if matching_updates.is_empty() {
            return Ok(Vec::new());
        }
        // Index discovery and tree reads can block for a retained repository.
        // Keep that work off the async executor that serves RPC streams.
        let git_dir = git_dir.to_path_buf();
        let path_updates = matching_updates.clone();
        let paths = crate::spawn_blocking(move || {
            let repo = if git_dir.as_os_str().is_empty() {
                None
            } else {
                Some(crate::git::repo::open_repository(&git_dir)?)
            };
            Ok::<_, anyhow::Error>(
                path_updates
                    .into_iter()
                    .filter_map(|update| {
                        let paths = if catalog_refs.contains(&update.ref_name) {
                            repo.as_ref()
                                .map(|repo| {
                                    compute_changed_paths_in_repo(
                                        repo,
                                        &update.old_oid,
                                        &update.new_oid,
                                    )
                                })
                                .unwrap_or_default()
                        } else if repo.as_ref().is_some_and(|repo| {
                            has_rbac_root(repo, &update.old_oid)
                                || has_rbac_root(repo, &update.new_oid)
                        }) {
                            vec!["rbac".to_owned()]
                        } else {
                            return None;
                        };
                        Some((update, paths))
                    })
                    .collect::<Vec<_>>(),
            )
        })
        .await??;

        Ok(paths
            .into_iter()
            .map(|(update, changed_paths)| {
                let authorization = Some(hook_ctx.callback_authorization(vec![(&update).into()]));
                AdmitResourcesRequest {
                    repository_id: repository_id.to_owned(),
                    ref_name: update.ref_name,
                    old_commit_sha: update.old_oid,
                    new_commit_sha: update.new_oid,
                    changed_paths,
                    authorization,
                }
            })
            .collect())
    }
}

#[async_trait]
impl AdmissionHandler for AdmissionControlHandler {
    fn receipt_catalog_refs(&self, updates: &[RefUpdate]) -> Vec<String> {
        updates
            .iter()
            .filter(|update| self.branch_pattern.is_match(&update.ref_name))
            .map(|update| update.ref_name.clone())
            .collect()
    }

    async fn admit(
        &self,
        _phase: &str,
        updates: &[RefUpdate],
        repository_id: &str,
        git_dir: &Path,
        hook_ctx: &HookContext,
    ) -> anyhow::Result<AdmissionDecision> {
        tracing::info!(
            actor_subject = %hook_ctx.actor_subject,
            actor_auth_method = %hook_ctx.actor_auth_method,
            repository_id,
            "admission_control: admit called"
        );
        for req in self
            .callback_requests(updates, repository_id, git_dir, hook_ctx)
            .await?
        {
            let client = self.client.clone();
            let service_token = self.service_token.clone();
            let ref_name = req.ref_name.clone();
            tokio::spawn(async move {
                if let Err(e) =
                    deliver_admission_callback(client, req, &service_token, Duration::from_secs(30))
                        .await
                {
                    error!(
                        ref_name = %ref_name,
                        error = %e,
                        "admit_resources_error"
                    );
                }
            });
        }

        Ok(AdmissionDecision::Accept)
    }
}

async fn deliver_admission_callback(
    mut client: CatalogServiceClient<tonic::transport::Channel>,
    request: AdmitResourcesRequest,
    service_token: &str,
    attempt_timeout: Duration,
) -> Result<(), tonic::Status> {
    let mut attempt = 0;
    loop {
        attempt += 1;
        // Reusing the accepted snapshot is safe; reusing its signed transport
        // request is not, because the receiver retains RPC nonces.
        let result = match crate::auth::interceptor::callback_request(
            request.clone(),
            service_token,
            "/gitstore.catalog.v1.CatalogService/AdmitResources",
        ) {
            Ok(signed) => tokio::time::timeout(attempt_timeout, client.admit_resources(signed))
                .await
                .unwrap_or_else(|_| {
                    Err(tonic::Status::deadline_exceeded(
                        "admission callback timed out",
                    ))
                })
                .map(|_| ()),
            Err(error) => Err(error),
        };
        match result {
            Err(error)
                if attempt < 3
                    && matches!(
                        error.code(),
                        tonic::Code::Unavailable
                            | tonic::Code::DeadlineExceeded
                            | tonic::Code::ResourceExhausted
                            | tonic::Code::Aborted
                            | tonic::Code::Internal
                    ) =>
            {
                tokio::time::sleep(Duration::from_millis(100 * attempt)).await;
            }
            outcome => return outcome,
        }
    }
}

// ---------------------------------------------------------------------------
// Path computation helper
// ---------------------------------------------------------------------------

fn has_rbac_root(repo: &gix::Repository, commit: &str) -> bool {
    let Ok(commit) = gix::ObjectId::from_hex(commit.as_bytes()) else {
        return false;
    };
    let Some(root) = get_tree_id(repo, commit) else {
        return false;
    };
    let Ok(tree) = repo.find_tree(root) else {
        return false;
    };
    tree.decode()
        .is_ok_and(|tree| tree.entries.iter().any(|entry| entry.filename == "rbac"))
}

/// Compute the changed file paths for one ref update, given an already-open
/// repository.  The tree-walking logic lives in `crate::git::tree_diff`.
///
/// - `old_oid` all-zeros → full tree of `new_oid` (new branch).
/// - `new_oid` all-zeros → full tree of `old_oid` (branch deletion).
/// - Both non-zero → paths that differ between the two commit trees.
/// - Any parse/lookup error → returns `vec![]` (Go falls back to a full scan).
fn compute_changed_paths_in_repo(
    repo: &gix::Repository,
    old_oid: &str,
    new_oid: &str,
) -> Vec<String> {
    let zero = "0".repeat(40);

    if new_oid == zero {
        let Ok(old_id) = gix::ObjectId::from_hex(old_oid.as_bytes()) else {
            return vec![];
        };
        let Some(tree_id) = get_tree_id(repo, old_id) else {
            return vec![];
        };
        let mut paths = Vec::new();
        collect_paths_from_tree(repo, tree_id, "", &mut paths);
        return paths;
    }

    let Ok(new_id) = gix::ObjectId::from_hex(new_oid.as_bytes()) else {
        return vec![];
    };

    if old_oid == zero {
        let Some(tree_id) = get_tree_id(repo, new_id) else {
            return vec![];
        };
        let mut paths = Vec::new();
        collect_paths_from_tree(repo, tree_id, "", &mut paths);
        return paths;
    }

    let Ok(old_id) = gix::ObjectId::from_hex(old_oid.as_bytes()) else {
        return vec![];
    };

    let old_tree = match get_tree_id(repo, old_id) {
        Some(id) => id,
        None => {
            let Some(new_tree) = get_tree_id(repo, new_id) else {
                return vec![];
            };
            let mut paths = Vec::new();
            collect_paths_from_tree(repo, new_tree, "", &mut paths);
            return paths;
        }
    };
    let Some(new_tree) = get_tree_id(repo, new_id) else {
        return vec![];
    };

    let mut paths = Vec::new();
    collect_diff_paths_from_trees(repo, old_tree, new_tree, "", &mut paths);
    paths
}

